package cn.linkdeck.qa;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.view.accessibility.AccessibilityNodeInfo;import android.widget.*;import cn.linkdeck.adb.*;import java.io.*;import java.net.*;import java.nio.*;import java.util.*;import java.util.regex.*;
public class Version012MotionChecks extends Version011RemoteChecks {
 boolean record;public void onCreate(Bundle args){record=args!=null&&"true".equals(args.getString("record"));super.onCreate(args);}
 void finger(View v,int action,float fraction)throws Exception{runOnMainSync(()->{long now=SystemClock.uptimeMillis();MotionEvent e=MotionEvent.obtain(now,now,action,v.getWidth()*fraction,v.getHeight()/2f,0);v.dispatchTouchEvent(e);e.recycle();});}
 float offset(VolumeGlide v)throws Exception{java.lang.reflect.Field f=VolumeGlide.class.getDeclaredField("offset");f.setAccessible(true);return f.getFloat(v);}
 public void onStart(){Bundle result=new Bundle();boolean success=false;AdbClient client=null;ServerSocket listener=null;ParcelFileDescriptor recording=null;long started=0;try{
  listener=new ServerSocket(0);final ServerSocket peer=listener;
  Thread server=new Thread(()->{try(Socket socket=peer.accept()){InputStream in=socket.getInputStream();OutputStream out=socket.getOutputStream();boolean hello=false;while(true){ByteBuffer h=ByteBuffer.wrap(exact(in,24)).order(ByteOrder.LITTLE_ENDIAN);int cmd=h.getInt(),local=h.getInt(),remote=h.getInt(),size=h.getInt();byte[] payload=exact(in,size);if(!hello){send(out,"CNXN",0x01000000,4096,"device::\0".getBytes("UTF-8"));hello=true;continue;}if(cmd==code("OPEN")){String service=new String(payload,"UTF-8");Matcher key=Pattern.compile("input keyevent ([0-9]+)").matcher(service);if(key.find())events.add(Integer.parseInt(key.group(1)));Matcher tag=Pattern.compile("__LINKDECK_[0-9a-f]+__").matcher(service);if(!tag.find())throw new IOException("Expected legacy wrapper");send(out,"OKAY",local+100,local,new byte[0]);send(out,"WRTE",local+100,local,("\n"+tag.group()+"0\n").getBytes("UTF-8"));send(out,"CLSE",local+100,local,new byte[0]);}}}catch(Exception ignored){}});server.setDaemon(true);server.start();
  getTargetContext().getSharedPreferences("linkdeck",0).edit().putBoolean("resume_connection",false).putBoolean("reduce_motion",false).commit();
  activity=startActivitySync(new Intent().setClassName("cn.linkdeck.adb","cn.linkdeck.adb.MainActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));Thread.sleep(1600);
  if(record){recording=getUiAutomation().executeShellCommand("screenrecord --time-limit 45 --bit-rate 2500000 /sdcard/linkdeck-0.11.2-motion.mp4");started=SystemClock.uptimeMillis();Thread.sleep(1000);}
  for(int i=0;i<5;i++){final int index=i;call("show",new Class[]{int.class},i);View page=(View)field("body");check(page.getTag().toString().endsWith(":true")&&page.getAnimation()!=null,"tab "+i+" starts its finite entry motion");Thread.sleep(1100);shot("v012-tab-"+i);}
  client=new AdbClient();client.connect("127.0.0.1",listener.getLocalPort(),new AdbIdentity(new File(getTargetContext().getCacheDir(),"qa012-peer-"+UUID.randomUUID())));set("adb",client);set("device","动效演示 · 本地测试通道");set("host","127.0.0.1");call("show",new Class[]{int.class},1);Thread.sleep(1100);
  TextView power=(TextView)find(activity.getWindow().getDecorView(),"电源 / 待机");check(power.getCurrentTextColor()==android.graphics.Color.TRANSPARENT&&power.getContentDescription().toString().contains("待机"),"power is an accessible icon control");
  VolumeGlide glide=(VolumeGlide)field("volumeGlide");check(glide.getContentDescription().toString().contains("松手回中"),"relative slider explains its actual semantics");finger(glide,MotionEvent.ACTION_DOWN,.5f);Thread.sleep(250);check(count(24)==0&&count(25)==0,"neutral hold sends no volume command");
  for(int i=1;i<=8;i++){finger(glide,MotionEvent.ACTION_MOVE,.5f+i*.055f);Thread.sleep(70);}waitFor("drag right repeats real VOLUME_UP commands",()->count(24)>=3);finger(glide,MotionEvent.ACTION_UP,.94f);waitFor("release lets the one in-flight key finish",()->!((java.util.concurrent.atomic.AtomicBoolean)field("keyPending")).get());int released=count(24);Thread.sleep(800);check(count(24)==released&&Math.abs(offset(glide))<.01,"release stops commands and springs to center");
  finger(glide,MotionEvent.ACTION_DOWN,.08f);waitFor("drag left sends real VOLUME_DOWN",()->count(25)>=1);finger(glide,MotionEvent.ACTION_CANCEL,.08f);Thread.sleep(500);int canceled=count(25);Thread.sleep(400);check(count(25)==canceled&&Math.abs(offset(glide))<.01,"cancel stops repeat and resets thumb");
  int before=count(24);runOnMainSync(()->glide.performAccessibilityAction(AccessibilityNodeInfo.ACTION_SCROLL_FORWARD,null));waitFor("accessibility slider action sends one volume step",()->count(24)==before+1);Thread.sleep(450);check(count(24)==before+1,"accessibility action does not start a repeat loop");shot("v012-remote");
  finger(glide,MotionEvent.ACTION_DOWN,.95f);Thread.sleep(250);tap("电源 / 待机");waitFor("icon power retains standby confirmation",()->dialogHas("切换电源状态"));Thread.sleep(400);int focusCount=count(24);Thread.sleep(600);check(count(24)==focusCount,"opening a sheet stops the held volume gesture");dialogTap("取消");check(count(26)==0,"cancel icon power sends no power command");
  finger(glide,MotionEvent.ACTION_DOWN,.95f);Thread.sleep(300);call("show",new Class[]{int.class},0);Thread.sleep(400);int detached=count(24);Thread.sleep(500);check(count(24)==detached,"leaving a tab stops volume repeats");
  call("show",new Class[]{int.class},1);Thread.sleep(700);client.close();set("adb",null);VolumeGlide offline=(VolumeGlide)field("volumeGlide");int total=events.size();finger(offline,MotionEvent.ACTION_DOWN,.95f);waitFor("offline volume remains connection-gated",()->dialogHas("连接后即可操作"));check(events.size()==total,"offline gesture sends no volume command");dialogTap("继续浏览");
  getTargetContext().getSharedPreferences("linkdeck",0).edit().putBoolean("reduce_motion",true).commit();call("show",new Class[]{int.class},1);check(((View)field("body")).getAnimation()==null,"reduced motion disables tab entry animations");VolumeGlide quiet=(VolumeGlide)field("volumeGlide");runOnMainSync(()->quiet.feedback(1));check(offset(quiet)==0,"reduced motion disables slider spring animation");getTargetContext().getSharedPreferences("linkdeck",0).edit().putBoolean("reduce_motion",false).commit();success=true;
 }catch(Throwable t){result.putString("stream",android.util.Log.getStackTraceString(t));}finally{if(client!=null)client.close();try{if(listener!=null)listener.close();if(started>0){long remaining=47000-(SystemClock.uptimeMillis()-started);if(remaining>0)Thread.sleep(remaining);}if(recording!=null)recording.close();}catch(Exception ignored){}}
 if(success)result.putString("stream","VERSION 012 MOTION INPUT PASSED: "+passes+" checks.\n");finish(success?-1:0,result);
 }
}
